/api/v1/admin/notification-channels:
  get:
    tags: [platform-admin]
    operationId: listNotificationChannels
    summary: "The two notification channels of an organization (email, enterprise_messaging), configured or not; the in-app inbox is always on and is not listed. notification_channel.configure or operations.read. ADR-0054 §3; REQ-S12-023."
    parameters:
      - $ref: "#/components/parameters/OrganizationIdQuery"
      - $ref: "#/components/parameters/Cursor"
      - $ref: "#/components/parameters/Limit"
    responses:
      "200":
        description: "OK."
        content:
          application/json:
            schema: { $ref: "#/components/schemas/NotificationChannelPage" }
      "400": { $ref: "#/components/responses/ValidationError" }
      "401": { $ref: "#/components/responses/Unauthenticated" }
      "403": { $ref: "#/components/responses/Forbidden" }
      "404": { $ref: "#/components/responses/NotFound" }
      "429": { $ref: "#/components/responses/RateLimited" }
/api/v1/admin/notification-channels/{channelKind}:
  parameters:
    - $ref: "#/components/parameters/ChannelKindPath"
    - $ref: "#/components/parameters/OrganizationIdQuery"
  get:
    tags: [platform-admin]
    operationId: getNotificationChannel
    summary: "One channel; ETag 0 when it was never configured (then it is disabled). ADR-0054 §3."
    responses:
      "200":
        description: "OK."
        headers:
          ETag: { $ref: "#/components/headers/ETagOrZero" }
        content:
          application/json:
            schema: { $ref: "#/components/schemas/NotificationChannel" }
      "400": { $ref: "#/components/responses/ValidationError" }
