+    notificationId: input.notificationId,
+    recipientUserId: input.recipientUserId,
+    locale: input.locale,
+    subject: headerSafe(fill(texts.subject, { product })),
+    text: compose(texts, line, product, input.deepLinkUrl),
+    deepLinkUrl: input.deepLinkUrl,
+  };
+}
