+    notificationId: "test",
+    recipientUserId: input.recipientUserId,
+    locale: input.locale,
+    subject: headerSafe(fill(texts.testSubject, { product })),
+    text: compose(texts, texts.testLine, product, input.linkUrl),
+    deepLinkUrl: input.linkUrl,
+  };
+}

