+} from "../platform/index.ts";
+import type { SecretProviderRegistry } from "../platform/secrets.ts";
+import { createBrandingReadPort } from "./branding-port.ts";
+import { createEmailChannel } from "../tasks/channels/email.ts";
+import {
+  CHANNEL_ADAPTER_AVAILABLE,
+  CHANNEL_KINDS,
+  SMTP_SECURITY_MODES,
