+  type ChannelSecretRef,
+  type SmtpSettings,
+} from "../tasks/channels/port.ts";
+import { channelLocaleOf, renderTestMessage } from "../tasks/channels/render.ts";
+
+const CONFIGURE: Permission = "notification_channel.configure";
+const READ: Permission = "operations.read";
+const JSON_BODY = ["application/json"] as const;
