    for (const code of ["ECONNECTION", "ETLS", "EAUTH", "EENVELOPE", "EPROTOCOL", "ECONFIG", "X"])
      expect(classifySmtpError({ code }).errorCode).toMatch(/^[a-z][a-z0-9_.]*$/);
  });
